fn copy(
    src: &Vec<i32>,
    s_start: usize,
    dest: &Vec<i32>,
    d_start: usize,
    len: usize,
) -> Vec<i32> {
    // Create a new vector by cloning the destination.
    // We'll overwrite the appropriate segment in place.
    let mut result = dest.clone();

    // Copy each element from src[s_start..s_start+len]
    // into result[d_start..d_start+len].
    for i in 0..len {
        result[d_start + i] = src[s_start + i];
    }

    result
}

